function setupScrollSpy(){var secs=document.querySelectorAll('section[id],.hero[id]'),sb=document.querySelectorAll('.sb-link[data-section]'),tb=document.querySelectorAll('.topbar-link[data-section]');if(!secs.length)return;var o=new IntersectionObserver(function(en){en.forEach(function(e){if(e.isIntersecting){var id=e.target.id;sb.forEach(function(l){l.classList.toggle('active',l.dataset.section===id||(id==='topics'&&['simulations','labs','videos'].indexOf(l.dataset.section)!==-1))});tb.forEach(function(l){l.classList.toggle('active',l.dataset.section===id||(id==='topics'&&['simulations','labs','videos'].indexOf(l.dataset.section)!==-1))})}})},{rootMargin:'-20% 0px -60% 0px',threshold:0});secs.forEach(function(s){o.observe(s)})}
function setupSectionReveal(){var secs=document.querySelectorAll('section[id]');secs.forEach(function(s){s.classList.add('section-reveal')});var o=new IntersectionObserver(function(en){en.forEach(function(e){if(e.isIntersecting){e.target.classList.add('visible');o.unobserve(e.target)}})},{rootMargin:'0px 0px -80px 0px',threshold:0.05});secs.forEach(function(s){o.observe(s)})}
