function buildApp(){var root=document.getElementById('root');var tl=C.topics.reduce(function(a,t){return a+t.lessons.length},0);C.hero.stats=[{text:C.topics.length+' Temas'},{text:tl+' Lecciones'},{text:(C.simulations.length+(C.customSims||[]).length)+' Simuladores'},{text:C.videos.length+' Videos'}];var sl=(C.nav||[]).map(function(n){return '<button class="sb-link" data-section="'+(n.href||'').replace('#','')+'"><span class="sb-icon">'+n.icon+'</span>'+n.label+'</button>'}).join('');root.innerHTML='<nav class="sidebar" id="sidebar"><div class="sb-head"><div class="logo-text">⚗️ '+C.site.name+'</div><p>'+(C.site.tagline||C.site.description)+'</p></div><div class="sb-nav"><div class="sb-section">Navegación</div><button class="sb-link active" data-section="hero"><span class="sb-icon">🏠</span>Inicio</button>'+sl+'<div class="sb-section">Más</div><button class="sb-link" data-section="faqs"><span class="sb-icon">❓</span>Preguntas</button><button class="sb-link" data-section="contact"><span class="sb-icon">💬</span>Contacto</button></div><div class="sb-foot"><strong>'+C.site.name+'</strong>© '+C.site.year+'</div></nav><div class="sb-overlay" id="sb-overlay"></div><div class="main-wrap"><div class="topbar" id="topbar"><button class="topbar-toggle" id="topbar-toggle">☰</button><span class="topbar-title">'+C.site.name+'</span><span class="topbar-badge">v'+(C.site.version||'2.0')+'</span></div><div class="app-view" id="view-hero"><section class="hero" id="hero"><div class="container"><div class="hero-grid"><div><div class="hero-badge"><div class="pulse"></div>'+C.hero.badge+'</div><h1>'+C.hero.title+'</h1><div class="hero-actions">'+(C.hero.cta||[]).map(function(b){return '<button class="btn btn-'+b.style+'" data-action="'+b.target+'">'+b.text+'</button>'}).join('')+'</div><div class="hero-stats">'+C.hero.stats.map(function(s){return '<div class="stat">'+s.text+'</div>'}).join('')+'</div></div><div class="hero-cards">'+(C.hero.cards||[]).map(function(c){return '<div class="hero-card"><div class="hc-icon">'+c.icon+'</div><div class="hc-title">'+c.title+'</div><div class="hc-desc">'+c.desc+'</div></div>'}).join('')+'</div></div></div><div class="hero-wave"><svg viewBox="0 0 1440 60" preserveAspectRatio="none"><path d="M0,40 C360,80 720,0 1440,40 L1440,60 L0,60 Z" fill="var(--bg)"/></svg></div></section></div><div class="app-view" id="view-topics"><section><div class="container"><div class="section-header"><div class="section-tag">📚 Temas</div><h2 class="section-title">Temas de Estudio</h2></div><div class="grid-3" id="topics-grid"></div></div></section></div><div class="app-view" id="view-simulations"><section><div class="container"><div class="section-header"><div class="section-tag">🧪 Ejemplos</div><h2 class="section-title">Ejemplos de Laboratorio</h2></div><div class="grid-3" id="sims-grid"></div></div></section></div><div class="app-view" id="view-labs"><section><div class="container"><div class="section-header"><div class="section-tag">🔬 Guías</div><h2 class="section-title">Guías de Laboratorio</h2></div><div class="grid-3" id="labs-grid"></div></div></section></div><div class="app-view" id="view-videos"><section><div class="container"><div class="section-header"><div class="section-tag">🎬 Videos</div><h2 class="section-title">Clases en Video</h2></div><div class="grid-3" id="videos-grid"></div></div></section></div><div class="app-view" id="view-periodic" style="display:none"><section id="periodic"><div class="container"><div class="section-header"><div class="section-tag">'+C.sections.periodic.tag+'</div><h2 class="section-title">'+C.sections.periodic.title+'</h2></div><div id="pt-wrapper"></div></div></section></div><div class="app-view" id="view-faqs" style="display:none"><section id="faqs"><div class="container"><div class="section-header"><div class="section-tag">Preguntas</div><h2 class="section-title">Preguntas Frecuentes</h2></div><div id="faq-list"></div></div></section></div><div class="app-view" id="view-contact" style="display:none"><section id="contact"><div class="container"><div class="section-header"><div class="section-tag">Contacto</div><h2 class="section-title">Contacto</h2></div><div id="contact-form-container"></div></div></section></div></div><div class="modal-overlay" id="topic-modal"><div class="modal" id="topic-modal-content"></div></div><div class="modal-overlay" id="lesson-modal"><div class="modal" id="lesson-modal-content"></div></div><div class="modal-overlay" id="lab-modal"><div class="modal" id="lab-modal-content"></div></div><div class="modal-overlay" id="sim-modal"><div class="modal" id="sim-modal-content"></div></div><div class="modal-overlay" id="video-modal"><div class="modal" id="video-modal-content"></div></div><div class="admin-overlay" id="admin-overlay"><div class="admin-panel"><div class="admin-header"><h2>⚙️ Administración</h2><div class="admin-header-actions"><button class="admin-apply" id="admin-apply">✅ Guardar cambios</button><button class="admin-download" id="admin-download">💾 Exportar</button><button class="admin-close" id="admin-close">✕</button></div></div><div class="admin-tabs" id="admin-tabs"></div><div class="admin-body" id="admin-body"></div></div></div><button class="feedback-fab" id="feedback-fab">💬</button><div class="feedback-panel" id="feedback-panel"><div class="feedback-head"><strong>Feedback</strong></div><div id="feedback-body"><div class="feedback-type"><button type="button" class="active" data-type="error">🐛 Error</button><button type="button" data-type="sugerencia">💡 Sugerencia</button></div><textarea class="feedback-textarea" id="feedback-text" placeholder="Describe el error o tu sugerencia..."></textarea><button class="feedback-submit" id="feedback-submit-btn">Enviar</button></div></div><button class="quicknav-fab" id="quicknav-fab">⚡</button><div class="quicknav-panel" id="quicknav-panel"><div class="quicknav-head">Navegación rápida</div>'+(C.nav||[]).map(function(n){return '<button class="quicknav-item" data-section="'+(n.href||'').replace('#','')+'">'+n.icon+'<span>'+n.label+'</span></button>'}).join('')+'<button class="quicknav-item" data-section="faqs">❓<span>Preguntas</span></button><button class="quicknav-item" data-section="contact">💬<span>Contacto</span></button></div>';renderTopics();renderSims();renderLabs();renderVideos();renderPeriodicTable();renderFAQs();renderContactForm()}
function renderTopics(){var g=document.getElementById('topics-grid');if(!g)return;g.innerHTML=C.topics.map(function(t,i){return '<div class="card" data-topic="'+i+'"><div class="card-bar" style="background:linear-gradient(90deg,'+t.color+',transparent)"></div><div class="card-body"><div class="card-icon">'+t.icon+'</div><div class="card-title">'+t.title+'</div><div class="card-meta"><span class="meta-left">'+t.lessons.length+' lecciones</span><span class="meta-right">'+t.tag+'</span></div></div><div class="card-foot">Explorar <span>→</span></div></div>'}).join('');g.querySelectorAll('.card').forEach(function(el){el.addEventListener('click',function(){openTopic(parseInt(el.dataset.topic))})})}
function renderSims(){var g=document.getElementById('sims-grid');if(!g)return;var all=C.simulations.concat(C.customSims||[]);g.innerHTML=all.map(function(s){return '<div class="card" data-sim="'+s.id+'"><div class="card-bar" style="background:linear-gradient(90deg,'+(s.color||'var(--cyan)')+',transparent)"></div><div class="card-body"><div class="card-icon">'+s.icon+'</div><div class="card-title">'+s.title+'</div><div class="card-meta"><span class="meta-left">Interactivo</span><span class="meta-right">'+(s.tag||'')+'</span></div></div><div class="card-foot">Simular <span>→</span></div></div>'}).join('');g.querySelectorAll('.card').forEach(function(el){el.addEventListener('click',function(){openSim(el.dataset.sim)})})}
function renderLabs(){var g=document.getElementById('labs-grid');if(!g)return;g.innerHTML=(C.labs||[]).map(function(l,i){return '<div class="card" data-lab="'+i+'"><div class="card-bar" style="background:linear-gradient(90deg,'+(l.color||'var(--emerald)')+',transparent)"></div><div class="card-body"><div class="card-icon">'+l.icon+'</div><div class="card-title">'+l.title+'</div><div class="card-meta"><span class="meta-left">Práctica</span><span class="meta-right">'+l.tag+'</span></div></div><div class="card-foot">Ver guía <span>→</span></div></div>'}).join('');g.querySelectorAll('.card').forEach(function(el){el.addEventListener('click',function(){openLab(parseInt(el.dataset.lab))})})}
function renderVideos(){var g=document.getElementById('videos-grid');if(!g)return;g.innerHTML=C.videos.map(function(v,i){return '<div class="video-card" data-vidx="'+i+'"><div class="video-thumb"><img src="https://img.youtube.com/vi/'+v.youtubeId+'/mqdefault.jpg" alt="'+v.title+'" loading="lazy"><div class="video-play"><div class="video-play-btn">▶</div></div><div class="video-dur">'+v.duration+'</div></div><div class="video-info"><span class="vi-tag">'+v.category+'</span><h3>'+v.title+'</h3></div></div>'}).join('');g.querySelectorAll('.video-card').forEach(function(el){el.addEventListener('click',function(){var v=C.videos[+el.dataset.vidx];openVideo(v.youtubeId,v.title)})})}
function renderPeriodicTable(){var w=document.getElementById('pt-wrapper');if(!w)return;var m={};C.elements.forEach(function(el){m[el.row+'-'+el.col]=el});function cell(el){if(!el)return '<div class="pt-cell pt-empty"></div>';return '<div class="pt-cell pt-'+el.cat+'" data-z="'+el.z+'" title="'+el.name+'"><span class="pt-z">'+el.z+'</span><span class="pt-sym">'+el.sym+'</span><span class="pt-name">'+el.name+'</span></div>'}var h='<div class="pt-row pt-header-row"><div class="pt-period-label"></div>';for(var c=1;c<=18;c++)h+='<div class="pt-group-label">'+c+'</div>';h+='</div>';for(var r=1;r<=7;r++){h+='<div class="pt-row"><div class="pt-period-label">'+r+'</div>';for(var c=1;c<=18;c++){if(r===6&&c===3){h+='<div class="pt-cell pt-lanthanide pt-ref"><span class="pt-z">57-71</span><span class="pt-sym">La-Lu</span><span class="pt-name">Lantánidos</span></div>';continue}if(r===7&&c===3){h+='<div class="pt-cell pt-actinide pt-ref"><span class="pt-z">89-103</span><span class="pt-sym">Ac-Lr</span><span class="pt-name">Actínidos</span></div>';continue}h+=cell(m[r+'-'+c])}h+='</div>'}var la='<div class="pt-row"><div class="pt-period-label pt-series-label">Lan</div>';for(var c=1;c<=18;c++){if(c<3||c>17){la+='<div class="pt-cell pt-empty"></div>';continue}la+=cell(m['9-'+c])}la+='</div>';var ac='<div class="pt-row"><div class="pt-period-label pt-series-label">Act</div>';for(var c=1;c<=18;c++){if(c<3||c>17){ac+='<div class="pt-cell pt-empty"></div>';continue}ac+=cell(m['10-'+c])}ac+='</div>';var cats=['alkali','alkaline','transition','post-trans','metalloid','nonmetal','halogen','noble','lanthanide','actinide'];var leg=cats.filter(function(x){return C.catLabels[x]}).map(function(x){return '<div class="pt-legend-item"><div class="pt-legend-dot" style="background:'+C.catColors[x]+'"></div><span>'+C.catLabels[x]+'</span></div>'}).join('');w.innerHTML='<div class="pt-outer"><div class="pt-scroll-hint">← Desliza para ver toda la tabla →</div><div class="pt-container-scroll"><div class="pt-table">'+h+'</div><div class="pt-separator"><span>Lantánidos & Actínidos</span></div><div class="pt-table pt-series">'+la+ac+'</div></div><div class="pt-legend">'+leg+'</div><div id="el-detail" class="el-detail"></div></div>';w.querySelectorAll('.pt-cell[data-z]').forEach(function(el){el.addEventListener('click',function(){showElement(parseInt(el.dataset.z))})});w.querySelectorAll('.pt-ref').forEach(function(el){el.addEventListener('click',function(){w.querySelector('.pt-separator').scrollIntoView({behavior:'smooth',block:'center'})})})}
function showElement(z){var el=C.elements.find(function(e){return e.z===z});if(!el)return;var d=document.getElementById('el-detail');if(!d)return;var row=el.row<=7?el.row:(el.row===9?6:7);d.innerHTML='<div class="el-card-big" style="background:'+C.catColors[el.cat]+'"><span class="el-card-z">'+el.z+'</span><span class="el-card-sym">'+el.sym+'</span><span class="el-card-mass">'+el.mass+'</span></div><div class="el-card-info"><h3>'+el.name+'</h3><div class="el-card-props"><div class="el-card-prop"><span class="el-card-prop-label">Masa</span><span class="el-card-prop-value">'+el.mass+' u</span></div><div class="el-card-prop"><span class="el-card-prop-label">Categoría</span><span class="el-card-prop-value">'+C.catLabels[el.cat]+'</span></div><div class="el-card-prop"><span class="el-card-prop-label">Período</span><span class="el-card-prop-value">'+row+'</span></div><div class="el-card-prop"><span class="el-card-prop-label">Grupo</span><span class="el-card-prop-value">'+(el.row<=7?el.col:'—')+'</span></div></div>'+(el.config?'<div class="el-card-config"><span>Config:</span> '+el.config+'</div>':'')+'</div><button class="el-detail-close" id="el-detail-close">✕</button>';d.classList.add('visible');d.scrollIntoView({behavior:'smooth',block:'nearest'});document.getElementById('el-detail-close').addEventListener('click',function(){d.classList.remove('visible')})}
function renderFAQs(){var l=document.getElementById('faq-list');if(!l)return;l.innerHTML=C.faqs.map(function(f,i){return '<div class="faq-item" id="faq-'+i+'"><button class="faq-q" data-faqid="'+i+'">'+f.q+'<span class="faq-chevron">▼</span></button><div class="faq-a"><div class="faq-a-inner">'+f.a+'</div></div></div>'}).join('');l.querySelectorAll('.faq-q').forEach(function(b){b.addEventListener('click',function(){document.getElementById('faq-'+b.dataset.faqid).classList.toggle('open')})})}
function renderContactForm(){var c=document.getElementById('contact-form-container');if(!c)return;c.innerHTML='<div class="contact-box"><div style="display:flex;align-items:center;gap:10px;margin-bottom:14px"><div style="width:36px;height:36px;background:var(--teal);border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:1rem">💬</div><div><h3>¿Dudas?</h3><p class="sub">Te responderemos.</p></div></div><form id="contact-form"><div class="form-row form-row-2"><div class="form-group"><label>Nombre</label><input type="text" required placeholder="Tu nombre"></div><div class="form-group"><label>Email</label><input type="email" required placeholder="tu@email.com"></div></div><div class="form-row"><div class="form-group"><label>Mensaje</label><textarea rows="4" required placeholder="Tu consulta..."></textarea></div></div><button type="submit" class="form-submit">📤 Enviar</button></form></div>';document.getElementById('contact-form').addEventListener('submit',function(e){e.preventDefault();c.innerHTML='<div class="contact-box"><div class="form-success"><div class="fs-icon">✅</div><h3 style="color:var(--white)">¡Enviado!</h3><p style="color:var(--text2)">Te responderemos pronto.</p><button class="btn btn-primary" id="send-another" style="margin-top:8px">Enviar otro</button></div></div>';document.getElementById('send-another').addEventListener('click',renderContactForm)})}
function openModal(id){document.getElementById(id).classList.add('open');document.body.style.overflow='hidden'}
function closeModal(id){document.getElementById(id).classList.remove('open');document.body.style.overflow=''}
function openTopic(idx){var t=C.topics[idx];if(!t)return;var c=document.getElementById('topic-modal-content');c.innerHTML='<div class="modal-header"><h2>'+t.icon+' '+t.title+'</h2><button class="modal-close" id="topic-close">✕</button></div><div class="modal-body"><p style="color:var(--text);margin-bottom:20px;line-height:1.7">'+t.desc+'</p><h3 style="margin-bottom:12px;font-weight:700;color:var(--white)">📚 Lecciones</h3><div class="topic-lessons">'+t.lessons.map(function(l,i){var has=C.lessonContent&&C.lessonContent[l];return '<div class="topic-lesson-item'+(has?' clickable':'')+'" '+(has?'data-lesson="'+l+'"':'')+'><span class="tli-num">'+(i+1)+'</span><span class="tli-title">'+l+'</span>'+(has?'<span class="tli-arrow">→</span>':'')+'</div>'}).join('')+'</div></div>';document.getElementById('topic-close').addEventListener('click',function(){closeModal('topic-modal')});c.querySelectorAll('.topic-lesson-item[data-lesson]').forEach(function(el){el.addEventListener('click',function(){closeModal('topic-modal');setTimeout(function(){openLesson(el.dataset.lesson)},200)})});openModal('topic-modal')}
function openLesson(name){var secs=C.lessonContent?C.lessonContent[name]:null;var quiz=(C.quizData?C.quizData[name]:null)||(C.quizData?C.quizData['_default']:null)||[];var c=document.getElementById('lesson-modal-content');var tp=C.topics.find(function(t){return t.lessons.indexOf(name)!==-1});var html='<div class="modal-header"><h2>📖 '+name+'</h2><button class="modal-close" id="lesson-close">✕</button></div><div class="modal-body lesson-content"><div class="lesson-meta"><span class="lm-topic">'+(tp?tp.title:'')+'</span></div>';if(secs&&secs.length)secs.forEach(function(s){html+='<h3>'+s.t+'</h3><div class="lesson-section-content">'+parseMd(s.c)+'</div>'});else html+='<p style="color:var(--text2);text-align:center;padding:30px">Contenido en desarrollo...</p>';if(quiz.length)html+='<div style="margin-top:24px;padding-top:20px;border-top:1px solid var(--border)"><button class="btn btn-primary" id="start-quiz">📝 Evalúate</button></div>';html+='</div>';c.innerHTML=html;document.getElementById('lesson-close').addEventListener('click',function(){closeModal('lesson-modal')});var qb=document.getElementById('start-quiz');if(qb)qb.addEventListener('click',function(){startQuiz(name,quiz)});openModal('lesson-modal')}
function startQuiz(title,qs){var cur=0,sc=0;var c=document.getElementById('lesson-modal-content');function rq(){var q=qs[cur];c.innerHTML='<div class="modal-header"><h2>📝 Quiz: '+title+'</h2><button class="modal-close" id="qc">✕</button></div><div class="modal-body"><div class="quiz-progress"><div class="quiz-progress-fill" style="width:'+(cur/qs.length*100)+'%"></div></div><div style="display:flex;justify-content:space-between;margin-bottom:16px;font-size:.78rem;color:var(--text2)"><span>Pregunta '+(cur+1)+' de '+qs.length+'</span><span>✅ '+sc+'</span></div><div style="background:var(--bg);border:1px solid var(--border);border-radius:var(--r);padding:16px;margin-bottom:16px"><h3 style="font-size:.95rem;font-weight:700;color:var(--white);line-height:1.5">'+q.q+'</h3></div><div class="quiz-options">'+q.opts.map(function(o,i){return '<button class="quiz-option" data-opt="'+i+'">'+o+'</button>'}).join('')+'</div></div>';document.getElementById('qc').addEventListener('click',function(){closeModal('lesson-modal')});c.querySelectorAll('.quiz-option').forEach(function(b){b.addEventListener('click',function(){var s=parseInt(b.dataset.opt);if(s===q.correct)sc++;c.querySelectorAll('.quiz-option').forEach(function(x,i){x.style.pointerEvents='none';if(i===q.correct){x.style.background='var(--emerald)';x.style.color='#fff'}else if(i===s&&s!==q.correct){x.style.background='var(--rose)';x.style.color='#fff'}});if(q.exp){var d=document.createElement('div');d.style.cssText='margin-top:12px;padding:12px;background:rgba(13,148,136,.05);border:1px solid rgba(13,148,136,.12);border-radius:var(--r3);font-size:.78rem;color:var(--text);line-height:1.6';d.innerHTML='<strong>💡</strong> '+q.exp;c.querySelector('.quiz-options').after(d)}setTimeout(function(){cur++;if(cur<qs.length)rq();else sr()},2000)})})}function sr(){var p=Math.round(sc/qs.length*100);c.innerHTML='<div class="modal-header"><h2>📝 Resultados</h2><button class="modal-close" id="qc">✕</button></div><div class="modal-body" style="text-align:center;padding:40px 20px"><div style="font-size:3rem;margin-bottom:8px">'+(p>=70?'🎉':'📖')+'</div><h3 style="font-weight:800;color:var(--white);font-size:1.2rem">'+(p>=70?'¡Excelente!':'Sigue practicando')+'</h3><p style="color:var(--text2);margin:8px 0">'+sc+' de '+qs.length+' ('+p+'%)</p><div style="width:100%;max-width:200px;height:8px;background:var(--border);border-radius:4px;margin:16px auto;overflow:hidden"><div style="width:'+p+'%;height:100%;background:'+(p>=70?'var(--emerald)':'var(--amber)')+';border-radius:4px"></div></div><button class="btn btn-primary" id="qr" style="margin-top:16px">🔄 Reintentar</button></div>';document.getElementById('qc').addEventListener('click',function(){closeModal('lesson-modal')});document.getElementById('qr').addEventListener('click',function(){cur=0;sc=0;rq()})}rq()}
function openLab(idx){var lab=(C.labs||[])[idx];if(!lab)return;var guide=C.labGuides?C.labGuides['lab-'+idx]:null;var c=document.getElementById('lab-modal-content');var html='<div class="modal-header"><h2>'+lab.icon+' '+lab.title+'</h2><button class="modal-close" id="lab-close">✕</button></div><div class="modal-body"><p style="color:var(--text);margin-bottom:16px;line-height:1.7">'+lab.desc+'</p>';if(guide){if(guide.safety)html+='<div class="lab-safety" style="margin-bottom:16px"><strong>⚠️ Seguridad:</strong><ul style="margin-top:6px;padding-left:18px">'+guide.safety.map(function(s){return '<li style="list-style:disc;font-size:.82rem;color:var(--text);margin-bottom:4px">'+s+'</li>'}).join('')+'</ul></div>';if(guide.materials)html+='<h4 style="margin:16px 0 8px;color:var(--white)">🧪 Materiales</h4><ul class="lab-materials">'+guide.materials.map(function(m){return '<li>'+m+'</li>'}).join('')+'</ul>';if(guide.procedure)html+='<h4 style="margin:16px 0 8px;color:var(--white)">📋 Procedimiento</h4><ol class="lab-steps">'+guide.procedure.map(function(s){return '<li>'+s.p+'</li>'}).join('')+'</ol>';if(guide.obs)html+='<div class="sim-info"><div>📝</div><p>'+guide.obs+'</p></div>';if(guide.questions)html+='<h4 style="margin:16px 0 8px;color:var(--white)">❓ Preguntas</h4><ul style="padding-left:18px">'+guide.questions.map(function(q){return '<li style="list-style:decimal;font-size:.82rem;color:var(--text);margin-bottom:6px;line-height:1.6">'+q+'</li>'}).join('')+'</ul>'}else html+='<p style="color:var(--text2);text-align:center;padding:20px">Guía en desarrollo...</p>';html+='</div>';c.innerHTML=html;document.getElementById('lab-close').addEventListener('click',function(){closeModal('lab-modal')});openModal('lab-modal')}
var simEngines={'sim-ph':function(c){var pH=7;function r(){var H=Math.pow(10,-pH),OH=Math.pow(10,-(14-pH)),tp=pH<7?'Ácido':pH>7?'Básico':'Neutro',co=pH<3?'#ef4444':pH<5?'#f97316':pH<7?'#eab308':pH===7?'#22c55e':pH<10?'#3b82f6':pH<12?'#6366f1':'#8b5cf6';c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>🌡️ Medidor de pH</h4><div class="control-group"><label>pH: <span style="color:'+co+';font-weight:800">'+pH+'</span></label><input type="range" min="0" max="14" step="0.5" value="'+pH+'" id="sph"></div><div style="text-align:center;padding:12px;background:'+co+'20;border-radius:var(--r2);border:1px solid '+co+'40"><div style="font-size:2rem;font-weight:900;color:'+co+'">'+pH+'</div><div style="font-size:.8rem;font-weight:700;color:'+co+'">'+tp+'</div></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">[H⁺]</div><div class="rb-value" style="color:var(--rose)">'+H.toExponential(2)+' M</div></div><div class="result-box"><div class="rb-label">[OH⁻]</div><div class="rb-value" style="color:var(--blue)">'+OH.toExponential(2)+' M</div></div><div class="result-box"><div class="rb-label">pOH</div><div class="rb-value" style="color:var(--indigo)">'+(14-pH).toFixed(1)+'</div></div></div><div class="ph-bar"><div class="ph-bar-track"><div class="ph-bar-indicator" style="left:'+(pH/14*100)+'%;background:'+co+'"></div></div><div class="ph-bar-labels"><span>0 Ácido</span><span>7 Neutro</span><span>14 Básico</span></div></div></div></div>';c.querySelector('#sph').addEventListener('input',function(e){pH=+e.target.value;r()})}r()},'sim-estequio':function(c){var m=10;function r(){var mol=m/40;c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>🧮 Estequiometría</h4><div style="padding:10px;background:var(--bg);border:1px solid var(--border);border-radius:var(--r3);margin-bottom:12px;font-size:.75rem;color:var(--text)"><strong>NaOH + HCl → NaCl + H₂O</strong></div><div class="control-group"><label>Masa NaOH: <span>'+m+' g</span></label><input type="range" min="1" max="200" step="0.5" value="'+m+'" id="sem"></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">Moles</div><div class="rb-value" style="color:var(--teal)">'+mol.toFixed(4)+'</div></div><div class="result-box"><div class="rb-label">Masa NaCl</div><div class="rb-value" style="color:var(--blue)">'+(mol*58.44).toFixed(3)+' g</div></div><div class="result-box"><div class="rb-label">Partículas</div><div class="rb-value" style="color:var(--purple)">'+(mol*6.022e23).toExponential(3)+'</div></div></div></div></div>';c.querySelector('#sem').addEventListener('input',function(e){m=+e.target.value;r()})}r()},'sim-dilucion':function(c){var M1=1,V1=100,M2=0.1;function r(){var V2=(M1*V1)/M2;c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>💧 Diluciones</h4><div class="control-group"><label>M₁: <span>'+M1+' M</span></label><input type="range" min="0.1" max="10" step="0.1" value="'+M1+'" id="dm1"></div><div class="control-group"><label>V₁: <span>'+V1+' mL</span></label><input type="range" min="1" max="500" step="1" value="'+V1+'" id="dv1"></div><div class="control-group"><label>M₂: <span>'+M2+' M</span></label><input type="range" min="0.01" max="5" step="0.01" value="'+M2+'" id="dm2"></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">V₂</div><div class="rb-value" style="color:var(--teal)">'+V2.toFixed(2)+' mL</div></div><div class="result-box"><div class="rb-label">Factor</div><div class="rb-value" style="color:var(--blue)">'+(M1/M2).toFixed(2)+'x</div></div><div class="result-box"><div class="rb-label">Agua</div><div class="rb-value" style="color:var(--purple)">'+(V2-V1).toFixed(2)+' mL</div></div></div><div class="sim-info"><div>ℹ️</div><p>M₁V₁ = M₂V₂</p></div></div></div>';c.querySelector('#dm1').addEventListener('input',function(e){M1=+e.target.value;r()});c.querySelector('#dv1').addEventListener('input',function(e){V1=+e.target.value;r()});c.querySelector('#dm2').addEventListener('input',function(e){M2=+e.target.value;r()})}r()},'sim-config':function(c){var Z=1,ord=['1s','2s','2p','3s','3p','4s','3d','4p','5s','4d','5p'],mx={s:2,p:6,d:10,f:14},sp={'0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹'};function ts(n){return String(n).split('').map(function(d){return sp[d]||d}).join('')}function gc(z){var rem=z,res=[];for(var i=0;i<ord.length&&rem>0;i++){var t=ord[i][ord[i].length-1],max=mx[t],f=Math.min(rem,max);res.push(ord[i]+ts(f));rem-=f}return res.join(' ')}function r(){var el=C.elements.find(function(e){return e.z===Z});c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>⚛️ Config. Electrónica</h4><div class="control-group"><label>Z: <span style="font-weight:800;color:var(--teal)">'+Z+'</span></label><input type="range" min="1" max="36" step="1" value="'+Z+'" id="scz"></div>'+(el?'<div style="text-align:center;padding:14px;background:var(--bg);border:1px solid var(--border);border-radius:var(--r2)"><div style="font-size:1.6rem;font-weight:900;color:var(--white)">'+el.sym+'</div><div style="font-size:.82rem;color:var(--text)">'+el.name+'</div></div>':'')+'</div><div><div class="results-grid"><div class="result-box"><div class="rb-label">Configuración</div><div class="rb-value" style="color:var(--teal);font-size:.8rem">'+gc(Z)+'</div></div><div class="result-box"><div class="rb-label">Electrones</div><div class="rb-value" style="color:var(--blue)">'+Z+'</div></div></div><div class="sim-info"><div>ℹ️</div><p>Regla de Moeller</p></div></div></div>';c.querySelector('#scz').addEventListener('input',function(e){Z=+e.target.value;r()})}r()},'sim-nox':function(c){var cp=[{f:'H₂O',els:[{s:'H',n:1,c:2},{s:'O',n:-2,c:1}]},{f:'NaCl',els:[{s:'Na',n:1,c:1},{s:'Cl',n:-1,c:1}]},{f:'H₂SO₄',els:[{s:'H',n:1,c:2},{s:'S',n:6,c:1},{s:'O',n:-2,c:4}]},{f:'KMnO₄',els:[{s:'K',n:1,c:1},{s:'Mn',n:7,c:1},{s:'O',n:-2,c:4}]}],idx=0;function r(){var x=cp[idx],sum=x.els.reduce(function(a,e){return a+e.n*e.c},0);c.innerHTML='<div style="display:flex;flex-wrap:wrap;gap:5px;margin-bottom:14px">'+cp.map(function(comp,i){return '<button class="nb" data-i="'+i+'" style="padding:7px 12px;border-radius:var(--r3);font-weight:700;font-size:.78rem;cursor:pointer;border:1px solid '+(i===idx?'var(--indigo)':'var(--border)')+';min-height:36px;background:'+(i===idx?'var(--indigo)':'none')+';color:'+(i===idx?'#fff':'var(--text)')+'">'+comp.f+'</button>'}).join('')+'</div><div style="background:var(--bg);border:1px solid var(--border);border-radius:var(--r);padding:18px;text-align:center"><h4 style="font-size:1.2rem;font-weight:800;margin-bottom:14px;color:var(--white)">'+x.f+'</h4><div style="display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin-bottom:12px">'+x.els.map(function(e){return '<div style="background:var(--card);border:1px solid var(--border);border-radius:var(--r2);padding:10px 14px;text-align:center;min-width:60px"><div style="font-size:1.2rem;font-weight:800;color:var(--white)">'+e.s+'</div><div style="font-size:.9rem;font-weight:700;margin-top:3px;color:'+(e.n>=0?'var(--blue)':'#ef4444')+'">'+(e.n>0?'+':'')+e.n+'</div><div style="font-size:.55rem;color:var(--text2)">×'+e.c+'</div></div>'}).join('')+'</div><div style="font-size:.78rem;color:var(--text2)">Σ = <strong style="color:var(--teal)">'+sum+'</strong> '+(sum===0?'✅':'')+'</div></div>';c.querySelectorAll('.nb').forEach(function(b){b.addEventListener('click',function(){idx=parseInt(b.dataset.i);r()})})}r()},'sim-disol':function(c){var ms=4,pm=40,vs=100,msv=100,nH=1;function r(){var mol=ms/pm;c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>🧫 Concentración</h4><div class="control-group"><label>Masa: <span>'+ms+' g</span></label><input type="range" min="0.1" max="100" step="0.1" value="'+ms+'" id="dms"></div><div class="control-group"><label>PM: <span>'+pm+'</span></label><input type="range" min="1" max="500" step="1" value="'+pm+'" id="dpm"></div><div class="control-group"><label>Vol: <span>'+vs+' mL</span></label><input type="range" min="10" max="2000" step="10" value="'+vs+'" id="dvs"></div><div class="control-group"><label>Solvente: <span>'+msv+' g</span></label><input type="range" min="10" max="2000" step="10" value="'+msv+'" id="dmv"></div><div class="control-group"><label>n: <span>'+nH+'</span></label><input type="range" min="1" max="3" step="1" value="'+nH+'" id="dnh"></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">Moles</div><div class="rb-value" style="color:var(--teal)">'+mol.toFixed(4)+'</div></div><div class="result-box"><div class="rb-label">M</div><div class="rb-value" style="color:var(--blue)">'+(mol/(vs/1000)).toFixed(4)+'</div></div><div class="result-box"><div class="rb-label">N</div><div class="rb-value" style="color:var(--purple)">'+(mol/(vs/1000)*nH).toFixed(4)+'</div></div><div class="result-box"><div class="rb-label">m</div><div class="rb-value" style="color:var(--orange)">'+(mol/(msv/1000)).toFixed(4)+'</div></div></div></div></div>';c.querySelector('#dms').addEventListener('input',function(e){ms=+e.target.value;r()});c.querySelector('#dpm').addEventListener('input',function(e){pm=+e.target.value;r()});c.querySelector('#dvs').addEventListener('input',function(e){vs=+e.target.value;r()});c.querySelector('#dmv').addEventListener('input',function(e){msv=+e.target.value;r()});c.querySelector('#dnh').addEventListener('input',function(e){nH=+e.target.value;r()})}r()},'sim-tit':function(c){var vol=0,Ca=0.1,Va=25,Cb=0.1;function cp(v){var mA=Ca*Va/1000,mB=Cb*v/1000;if(mB<mA)return -Math.log10((mA-mB)/((Va+v)/1000));if(Math.abs(mB-mA)<0.0001)return 7;return 14+Math.log10((mB-mA)/((Va+v)/1000))}function r(){var pH=cp(vol),veq=(Ca*Va)/Cb;c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>🧪 Titulación</h4><div style="padding:8px;background:var(--bg);border:1px solid var(--border);border-radius:var(--r3);margin-bottom:10px;font-size:.72rem;color:var(--text)">HCl '+Ca+'M ('+Va+' mL) + NaOH '+Cb+'M</div><div class="control-group"><label>Vol NaOH: <span>'+vol+' mL</span></label><input type="range" min="0" max="50" step="0.5" value="'+vol+'" id="stv"></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">pH</div><div class="rb-value" style="color:'+(pH<7?'var(--rose)':pH>7?'var(--blue)':'var(--emerald)')+'">'+pH.toFixed(2)+'</div></div><div class="result-box"><div class="rb-label">V equiv.</div><div class="rb-value" style="color:var(--purple)">'+veq.toFixed(1)+' mL</div></div><div class="result-box"><div class="rb-label">Estado</div><div class="rb-value" style="color:var(--teal);font-size:.75rem">'+(vol<veq?'Antes PE':vol>veq?'Después PE':'¡Equiv.!')+'</div></div></div></div></div>';c.querySelector('#stv').addEventListener('input',function(e){vol=+e.target.value;r()})}r()},'sim-valor':function(c){var Cb=0.1,Vb=25,Va=20;function r(){var Ca=(Cb*Vb)/Va;c.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>⚗️ Valoración</h4><div class="control-group"><label>C_base: <span>'+Cb+' M</span></label><input type="range" min="0.01" max="1" step="0.01" value="'+Cb+'" id="vcb"></div><div class="control-group"><label>V_base: <span>'+Vb+' mL</span></label><input type="range" min="0.5" max="50" step="0.5" value="'+Vb+'" id="vvb"></div><div class="control-group"><label>V_ácido: <span>'+Va+' mL</span></label><input type="range" min="1" max="100" step="1" value="'+Va+'" id="vva"></div></div><div><div class="results-grid"><div class="result-box"><div class="rb-label">C_ácido</div><div class="rb-value" style="color:var(--teal)">'+Ca.toFixed(4)+' M</div></div><div class="result-box"><div class="rb-label">°Dornic</div><div class="rb-value" style="color:var(--rose)">'+(Ca*100*1000/10).toFixed(1)+'</div></div><div class="result-box"><div class="rb-label">mol base</div><div class="rb-value" style="color:var(--blue)">'+(Cb*Vb/1000).toExponential(3)+'</div></div></div></div></div>';c.querySelector('#vcb').addEventListener('input',function(e){Cb=+e.target.value;r()});c.querySelector('#vvb').addEventListener('input',function(e){Vb=+e.target.value;r()});c.querySelector('#vva').addEventListener('input',function(e){Va=+e.target.value;r()})}r()},'sim-glosario':function(c){var terms=[{t:'Ácido',d:'Dona protones (H⁺).'},{t:'Base',d:'Acepta protones (H⁺).'},{t:'pH',d:'pH = -log[H⁺]. Escala 0-14.'},{t:'Mol',d:'6.022 × 10²³ entidades.'},{t:'Molaridad',d:'mol/L de solución.'},{t:'Normalidad',d:'eq-g/L. N = M × factor.'},{t:'Molalidad',d:'mol/kg solvente.'},{t:'Valoración',d:'Determina concentración desconocida.'},{t:'Indicador',d:'Cambia color según pH.'},{t:'Punto equiv.',d:'mol ácido = mol base.'},{t:'Estequiometría',d:'Cálculo de cantidades en reacciones.'},{t:'Reactivo limitante',d:'Se consume primero.'}],se='';function r(){var f=terms.filter(function(t){return t.t.toLowerCase().indexOf(se.toLowerCase())!==-1||t.d.toLowerCase().indexOf(se.toLowerCase())!==-1});c.innerHTML='<div style="margin-bottom:16px"><input type="text" placeholder="🔍 Buscar..." value="'+se+'" id="sgs" style="width:100%;padding:10px 14px;border:1px solid var(--border);border-radius:var(--r3);font-size:.82rem;color:var(--text);background:var(--bg)"></div><div style="display:flex;flex-direction:column;gap:6px">'+f.map(function(t){return '<div style="padding:12px 14px;background:var(--card);border:1px solid var(--border);border-radius:var(--r3)"><strong style="color:var(--white);font-size:.85rem">'+t.t+'</strong><p style="color:var(--text);font-size:.78rem;margin-top:4px;line-height:1.55">'+t.d+'</p></div>'}).join('')+'</div>';c.querySelector('#sgs').addEventListener('input',function(e){se=e.target.value;r()})}r()}};
function openSim(id){var sim=C.simulations.find(function(s){return s.id===id}),csim=(C.customSims||[]).find(function(s){return s.id===id}),target=sim||csim;if(!target)return;var mc=document.getElementById('sim-modal-content');mc.innerHTML='<div class="modal-header"><h2>'+target.icon+' '+target.title+'</h2><button class="modal-close" id="sim-close">✕</button></div>';var bd=document.createElement('div');bd.className='modal-body';mc.appendChild(bd);if(simEngines[id])simEngines[id](bd);else if(csim)buildCustomSim(csim,bd);else bd.innerHTML='<p style="text-align:center;padding:40px;color:var(--text2)">En desarrollo...</p>';document.getElementById('sim-close').addEventListener('click',function(){closeModal('sim-modal')});openModal('sim-modal')}
function buildCustomSim(cfg,ct){var st={};cfg.inputs.forEach(function(inp){st[inp.key]=inp.default||0});function calc(f){try{return new Function(Object.keys(st).join(','),'return '+f).apply(null,Object.values(st))||0}catch(e){return 0}}function r(){ct.innerHTML='<div class="sim-grid"><div class="sim-controls"><h4>⚙️ Parámetros</h4>'+cfg.inputs.map(function(inp){return '<div class="control-group"><label>'+inp.label+': <span>'+st[inp.key]+' '+inp.unit+'</span></label><input type="range" min="'+inp.min+'" max="'+inp.max+'" step="'+inp.step+'" value="'+st[inp.key]+'" data-key="'+inp.key+'"></div>'}).join('')+'</div><div><div class="results-grid">'+cfg.outputs.map(function(out){return '<div class="result-box"><div class="rb-label">'+out.label+'</div><div class="rb-value" style="color:'+(out.color||'var(--teal)')+'">'+calc(out.formula).toFixed(out.decimals||3)+' '+out.unit+'</div></div>'}).join('')+'</div>'+(cfg.info?'<div class="sim-info"><div>ℹ️</div><p>'+cfg.info+'</p></div>':'')+'</div></div>';ct.querySelectorAll('input[type="range"]').forEach(function(el){el.addEventListener('input',function(){st[el.dataset.key]=+el.value;r()})})}r()}
function openVideo(id,title){var mc=document.getElementById('video-modal-content');mc.innerHTML='<div class="modal-header"><h2>'+title+'</h2><button class="modal-close" id="video-close">✕</button></div><div class="modal-body"><div class="vm-iframe"><iframe src="https://www.youtube.com/embed/'+id+'?autoplay=1&playsinline=1" allow="autoplay;encrypted-media" allowfullscreen></iframe></div></div>';document.getElementById('video-close').addEventListener('click',closeVideo);openModal('video-modal')}
function closeVideo(){var mc=document.getElementById('video-modal-content');var f=mc.querySelector('iframe');if(f)f.remove();closeModal('video-modal')}
var adminTabs=[{key:'site',label:'🏠 General'},{key:'hero',label:'🎯 Portada'},{key:'topics',label:'📚 Temas'},{key:'lessons',label:'📖 Lecciones'},{key:'sims',label:'🧪 Ejemplos Lab'},{key:'labs',label:'🔬 Guías Lab'},{key:'videos',label:'🎬 Videos'},{key:'faqs',label:'❓ Preguntas'}],activeTab=0,adminAuth=false;
function openAdmin(){if(!adminAuth){var p=prompt('🔒 Contraseña:');if(p!==C.admin.password){if(p!==null)toast('❌ Incorrecta');return}adminAuth=true}document.getElementById('admin-overlay').classList.add('open');drawAdmin()}
function closeAdmin(){document.getElementById('admin-overlay').classList.remove('open')}
function toast(m){var d=document.createElement('div');d.className='atoast';d.textContent=m;document.body.appendChild(d);setTimeout(function(){d.remove()},2500)}
function esc(v){return String(v!=null?v:'').replace(/"/g,'&quot;')}
function F(l,id,v,tp,ph,hp){var h=hp?'<span style="font-size:.6rem;font-weight:400;color:var(--text2);text-transform:none;letter-spacing:0;margin-left:6px">— '+hp+'</span>':'';if(tp==='textarea')return '<div class="ae"><label>'+l+h+'</label><textarea id="'+id+'" rows="4" placeholder="'+(ph||'')+'">'+(v!=null?v:'')+'</textarea></div>';return '<div class="ae"><label>'+l+h+'</label><input id="'+id+'" value="'+esc(v)+'" placeholder="'+(ph||'')+'"></div>'}
function sec(ic,ti){return '<div style="display:flex;align-items:center;gap:8px;margin:18px 0 10px;padding-bottom:8px;border-bottom:1px solid var(--border)"><span style="font-size:1.1rem">'+ic+'</span><h4 style="font-size:.82rem;font-weight:700;color:var(--white)">'+ti+'</h4></div>'}
function drawAdmin(){var te=document.getElementById('admin-tabs'),bo=document.getElementById('admin-body');if(!te||!bo)return;te.innerHTML=adminTabs.map(function(t,i){return '<button class="admin-tab'+(i===activeTab?' active':'')+'" data-i="'+i+'">'+t.label+'</button>'}).join('');te.querySelectorAll('.admin-tab').forEach(function(b){b.addEventListener('click',function(){activeTab=parseInt(b.dataset.i);drawAdmin()})});var k=adminTabs[activeTab].key;var inf=function(t){return '<div class="ainfo"><span>💡</span><span>'+t+'</span></div>'};
if(k==='site'){bo.innerHTML=inf('Estos datos identifican tu plataforma. El nombre y la descripción aparecen en el navegador.')+sec('🏷️','Identidad')+F('Nombre','as-name',C.site.name,'','Ej: Química UNESUR','Aparece en la barra superior')+F('Eslogan','as-tag',C.site.tagline,'','Frase corta','Se muestra en el sidebar')+F('Descripción','as-desc',C.site.description,'textarea','Texto completo','Lo que Google muestra')+sec('📅','Datos')+F('Año','as-year',C.site.year,'','2024','Pie de página')+sec('🔒','Seguridad')+F('Contraseña del panel','as-pw',C.admin.password,'','Nueva contraseña','Ctrl+Shift+Q para abrir')}
else if(k==='hero'){bo.innerHTML=inf('Es lo primero que ve el estudiante. Los contadores se calculan automáticamente.')+sec('✨','Texto de bienvenida')+F('Etiqueta superior','ah-badge',C.hero.badge,'','Ej: Prof. Wilmer Molina','La pastilla sobre el título')+F('Título principal','ah-title',C.hero.title,'textarea','El título grande','Lo más visible de la página')+F('Subtítulo','ah-sub',C.hero.subtitle,'textarea','Texto complementario','Debajo del título')}
else if(k==='topics'){bo.innerHTML=inf('Cada tema agrupa lecciones relacionadas. El estudiante toca un tema para ver sus lecciones.')+C.topics.map(function(t,i){return '<div class="acard"><div class="acard-head"><h4><span class="acard-num">'+(i+1)+'</span>'+t.icon+' '+t.title+'</h4><button class="adel" onclick="if(confirm(\'¿Eliminar este tema?\')){C.topics.splice('+i+',1);drawAdmin()}">🗑️</button></div>'+F('Emoji','at-ic-'+i,t.icon,'','🧪','Emoji representativo')+F('Nombre','at-ti-'+i,t.title,'','','Aparece en la tarjeta')+F('Descripción','at-de-'+i,t.desc,'textarea','','Se ve al abrir el tema')+F('Etiqueta','at-tg-'+i,t.tag,'','Ej: Tema 1','Badge de la tarjeta')+F('Lecciones','at-le-'+i,t.lessons.join('\n'),'textarea','Una lección por línea','Deben coincidir con los nombres en Lecciones')+'</div>'}).join('')+'<button class="aadd" onclick="C.topics.push({title:\'Nuevo\',icon:\'📘\',desc:\'\',lessons:[\'Lección 1\'],tag:\'Nuevo\',color:\'var(--teal)\'});drawAdmin()">+ Agregar tema</button>'}
else if(k==='lessons'){var les=Object.keys(C.lessonContent||{});bo.innerHTML=inf('Contenido real que lee el estudiante. Para <b>negrita</b> usa dobles asteriscos: **así**.')+les.map(function(name,i){var secs=(C.lessonContent[name]||[]);return '<div class="acard"><div class="acard-head"><h4><span class="acard-num">'+(i+1)+'</span>📖 '+name+'</h4></div><p style="font-size:.68rem;color:var(--text2);margin-bottom:8px">'+secs.length+' sección'+(secs.length!==1?'es':'')+'</p>'+secs.map(function(s,si){return '<div style="padding:10px;background:#fff;border:1px solid var(--border);border-radius:var(--r3);margin-bottom:6px"><span style="font-size:.7rem;color:var(--teal);font-weight:700">Sección '+(si+1)+'</span>'+F('Título','al-'+i+'-'+si+'-t',s.t,'','','Subtítulo dentro de la lección')+F('Contenido','al-'+i+'-'+si+'-c',s.c,'textarea','Teoría, fórmulas y ejemplos','Cada línea vacía = nuevo párrafo')+'</div>'}).join('')+'</div>'}).join('')+sec('➕','Crear lección nueva')+'<div class="acard" style="border:2px dashed var(--teal)">'+F('Nombre','al-new-name','','','Ej: Enlace Covalente','Debe ser único')+'<button class="aadd" style="background:var(--teal);color:#fff;border:none" onclick="var n=document.getElementById(\'al-new-name\').value.trim();if(n){if(C.lessonContent[n]){toast(\'⚠️ Ya existe\')}else{C.lessonContent[n]=[{t:\'Introducción\',c:\'\'}];drawAdmin();toast(\'✅ Creada: \'+n)}}else{toast(\'❌ Escribe un nombre\')}">📖 Crear lección</button></div>'}
else if(k==='sims'){var all=C.simulations.concat(C.customSims||[]);bo.innerHTML=inf('Calculadoras interactivas. El estudiante mueve un deslizante y ve el resultado.')+sec('📋','Existentes')+all.map(function(s,i){return '<div class="acard"><div class="acard-head"><h4>'+s.icon+' '+s.title+'</h4></div>'+F('Nombre','as-sim-t-'+i,s.title,'','','Lo que ve el estudiante')+F('Descripción','as-sim-d-'+i,s.desc,'','','Qué calcula')+F('Etiqueta','as-sim-tg-'+i,s.tag,'','','Categoría')+'</div>'}).join('')+sec('➕','Crear ejemplo interactivo')+'<div class="acard" style="border:2px dashed var(--teal)"><p style="font-size:.72rem;color:var(--text2);margin-bottom:12px">El estudiante mueve un control deslizante y ve un resultado calculado.</p>'+F('Nombre','nsim-title','','','Ej: Calculadora de Moles','Título de la tarjeta')+'<div style="margin:14px 0 8px;padding:14px;background:rgba(59,130,246,.03);border:1px solid rgba(59,130,246,.15);border-radius:var(--r3)"><h4 style="font-size:.78rem;color:var(--blue);margin-bottom:4px">📊 ¿Qué controla el estudiante?</h4><p style="font-size:.65rem;color:var(--text2);margin-bottom:10px">El control deslizante que el estudiante mueve.</p><div class="ae-row ae-2">'+F('¿Qué variable?','nsim-v-label','','','Ej: Masa','Nombre visible')+F('¿Unidad?','nsim-v-unit','','','Ej: g','Al lado del valor')+'</div><div class="ae-row ae-2">'+F('¿Desde?','nsim-v-min','0','','0','Mínimo')+F('¿Hasta?','nsim-v-max','100','','100','Máximo')+'</div><div class="ae-row ae-2">'+F('¿De cuánto en cuánto?','nsim-v-step','1','','1','Incremento')+F('¿Empieza en?','nsim-v-default','50','','50','Valor inicial')+'</div></div><div style="margin:8px 0;padding:14px;background:rgba(13,148,136,.03);border:1px solid rgba(13,148,136,.15);border-radius:var(--r3)"><h4 style="font-size:.78rem;color:var(--teal);margin-bottom:4px">📐 ¿Qué resultado ve?</h4><p style="font-size:.65rem;color:var(--text2);margin-bottom:10px">Usa la letra <b>x</b> para representar el valor del deslizante.</p>'+F('Nombre del resultado','nsim-r-label','','','Ej: Moles','Sobre el número')+F('¿Cómo se calcula?','nsim-r-formula','','','Ej: x / 40','Usa x para la variable')+F('¿Unidad?','nsim-r-unit','','','Ej: mol','Del resultado')+'</div>'+F('Nota informativa','nsim-info','','','Ej: n = m / M','Opcional')+'<button class="aadd" style="background:var(--teal);color:#fff;border:none;width:100%;padding:12px;font-weight:700" id="nsim-create">🧪 Crear ejemplo</button></div>';setTimeout(function(){var btn=document.getElementById('nsim-create');if(btn)btn.addEventListener('click',function(){var t=document.getElementById('nsim-title').value.trim();if(!t){toast('❌ Escribe un nombre');return}var id='custom-'+t.toLowerCase().replace(/[^a-z0-9]/g,'-');if(!C.customSims)C.customSims=[];C.customSims.push({id:id,title:t,icon:'⚗️',desc:document.getElementById('nsim-info').value||'',tag:'',color:'var(--teal)',inputs:[{label:document.getElementById('nsim-v-label').value||'x',key:'x',unit:document.getElementById('nsim-v-unit').value||'',min:+(document.getElementById('nsim-v-min').value)||0,max:+(document.getElementById('nsim-v-max').value)||100,step:+(document.getElementById('nsim-v-step').value)||1,default:+(document.getElementById('nsim-v-default').value)||50}],outputs:[{label:document.getElementById('nsim-r-label').value||'Resultado',formula:document.getElementById('nsim-r-formula').value||'x',unit:document.getElementById('nsim-r-unit').value||'',color:'var(--teal)',decimals:3}],info:document.getElementById('nsim-info').value||''});toast('✅ "'+t+'" creado');drawAdmin()})},50)}
else if(k==='labs'){bo.innerHTML=inf('Guías paso a paso. Escribe cada elemento en una línea separada.')+(C.labs||[]).map(function(l,i){var g=C.labGuides?C.labGuides['lab-'+i]:null;return '<div class="acard"><div class="acard-head"><h4>'+l.icon+' '+l.title+'</h4></div>'+F('Nombre','alab-t-'+i,l.title,'','','Lo que ve el estudiante')+F('Descripción','alab-d-'+i,l.desc,'','','Una línea')+(g?sec('⚠️','Seguridad')+F('','alab-sf-'+i,(g.safety||[]).join('\n'),'textarea','Una norma por línea')+sec('🧪','Materiales')+F('','alab-mt-'+i,(g.materials||[]).join('\n'),'textarea','Un material por línea')+sec('📋','Procedimiento')+F('','alab-pr-'+i,(g.procedure||[]).map(function(s){return s.p}).join('\n'),'textarea','Un paso por línea')+sec('📝','Observaciones')+F('','alab-ob-'+i,g.obs||'')+sec('❓','Preguntas')+F('','alab-qu-'+i,(g.questions||[]).join('\n'),'textarea','Una pregunta por línea'):'')+'</div>'}).join('')}
else if(k==='videos'){bo.innerHTML=inf('Videos de YouTube. Solo necesitas el ID (lo que va después de v= en la URL).')+(C.videos||[]).map(function(v,i){return '<div class="acard"><div class="acard-head"><h4>🎬 '+v.title+'</h4><button class="adel" onclick="if(confirm(\'¿Eliminar?\')){C.videos.splice('+i+',1);drawAdmin()}">🗑️</button></div>'+F('Título','avid-t-'+i,v.title,'','','Nombre en la tarjeta')+'<div class="ae-row ae-2">'+F('ID de YouTube','avid-yt-'+i,v.youtubeId,'','Ej: 4MMWZeY-mU0','Solo el código')+F('Duración','avid-du-'+i,v.duration,'','Ej: 12:45')+'</div><div class="ae-row ae-2">'+F('Categoría','avid-ca-'+i,v.category,'','Ej: Átomo')+F('Descripción','avid-de-'+i,v.description)+'</div></div>'}).join('')+'<button class="aadd" onclick="C.videos.push({title:\'\',youtubeId:\'\',duration:\'\',category:\'\',description:\'\'});drawAdmin()">+ Agregar video</button>'}
else if(k==='faqs'){bo.innerHTML=inf('Preguntas frecuentes. El estudiante toca la pregunta y se despliega la respuesta.')+(C.faqs||[]).map(function(f,i){return '<div class="acard"><div class="acard-head"><h4>❓ Pregunta '+(i+1)+'</h4><button class="adel" onclick="if(confirm(\'¿Eliminar?\')){C.faqs.splice('+i+',1);drawAdmin()}">🗑️</button></div>'+F('¿Qué pregunta?','afaq-q-'+i,f.q,'','','Como la diría un estudiante')+F('Respuesta','afaq-a-'+i,f.a,'textarea','Clara y directa','Se ve al tocar la pregunta')+'</div>'}).join('')+'<button class="aadd" onclick="C.faqs.push({q:\'\',a:\'\'});drawAdmin()">+ Agregar pregunta</button>'}}
function applyAdmin(){try{var k=adminTabs[activeTab].key;if(k==='site'){C.site.name=document.getElementById('as-name').value;C.site.tagline=document.getElementById('as-tag').value;C.site.description=document.getElementById('as-desc').value;C.site.year=document.getElementById('as-year').value;C.admin.password=document.getElementById('as-pw').value||C.admin.password}else if(k==='hero'){C.hero.badge=document.getElementById('ah-badge').value;C.hero.title=document.getElementById('ah-title').value;C.hero.subtitle=document.getElementById('ah-sub').value}else if(k==='topics'){C.topics.forEach(function(t,i){var ic=document.getElementById('at-ic-'+i),ti=document.getElementById('at-ti-'+i),de=document.getElementById('at-de-'+i),tg=document.getElementById('at-tg-'+i),le=document.getElementById('at-le-'+i);if(ic)t.icon=ic.value;if(ti)t.title=ti.value;if(de)t.desc=de.value;if(tg)t.tag=tg.value;if(le)t.lessons=le.value.split('\n').filter(function(x){return x.trim()})})}else if(k==='lessons'){Object.keys(C.lessonContent||{}).forEach(function(name,i){(C.lessonContent[name]||[]).forEach(function(s,si){var t=document.getElementById('al-'+i+'-'+si+'-t'),c=document.getElementById('al-'+i+'-'+si+'-c');if(t)s.t=t.value;if(c)s.c=c.value})})}else if(k==='sims'){C.simulations.concat(C.customSims||[]).forEach(function(s,i){var t=document.getElementById('as-sim-t-'+i),d=document.getElementById('as-sim-d-'+i),tg=document.getElementById('as-sim-tg-'+i);if(t)s.title=t.value;if(d)s.desc=d.value;if(tg)s.tag=tg.value})}else if(k==='labs'){(C.labs||[]).forEach(function(l,i){var t=document.getElementById('alab-t-'+i),d=document.getElementById('alab-d-'+i);if(t)l.title=t.value;if(d)l.desc=d.value;var g=C.labGuides?C.labGuides['lab-'+i]:null;if(g){var sf=document.getElementById('alab-sf-'+i),mt=document.getElementById('alab-mt-'+i),pr=document.getElementById('alab-pr-'+i),ob=document.getElementById('alab-ob-'+i),qu=document.getElementById('alab-qu-'+i);if(sf)g.safety=sf.value.split('\n').filter(function(x){return x.trim()});if(mt)g.materials=mt.value.split('\n').filter(function(x){return x.trim()});if(pr)g.procedure=pr.value.split('\n').filter(function(x){return x.trim()}).map(function(p,n){return{n:n+1,p:p}});if(ob)g.obs=ob.value;if(qu)g.questions=qu.value.split('\n').filter(function(x){return x.trim()})}})}else if(k==='videos'){(C.videos||[]).forEach(function(v,i){var t=document.getElementById('avid-t-'+i),yt=document.getElementById('avid-yt-'+i),du=document.getElementById('avid-du-'+i),ca=document.getElementById('avid-ca-'+i),de=document.getElementById('avid-de-'+i);if(t)v.title=t.value;if(yt)v.youtubeId=yt.value;if(du)v.duration=du.value;if(ca)v.category=ca.value;if(de)v.description=de.value})}else if(k==='faqs'){(C.faqs||[]).forEach(function(f,i){var q=document.getElementById('afaq-q-'+i),a=document.getElementById('afaq-a-'+i);if(q)f.q=q.value;if(a)f.a=a.value})}buildApp();setupEventListeners();enhanceLayout();toast('✅ Cambios aplicados')}catch(e){alert('❌ '+e.message)}}
function downloadConfig(){var c='const CONFIG = '+JSON.stringify(CONFIG,null,2)+';\n';var b=new Blob([c],{type:'application/javascript'});var u=URL.createObjectURL(b);var a=document.createElement('a');a.href=u;a.download='config.js';a.click();URL.revokeObjectURL(u)}
function enhanceLayout(){var hero=document.querySelector('.hero');if(hero){var stats=hero.querySelector('.hero-stats');if(stats){var bar=document.createElement('div');bar.className='hero-bar';bar.innerHTML='<div class="hero-bar-inner"><div class="hero-bar-stats">'+C.hero.stats.map(function(s){var p=s.text.split(' ');return '<div class="hb-stat"><span class="hb-num">'+p[0]+'</span><span class="hb-label">'+p.slice(1).join(' ')+'</span></div>'}).join('')+'</div><div class="hero-bar-credit"><span>Cátedra del</span><strong>Prof. Wilmer Molina</strong></div></div>';stats.replaceWith(bar)}}}
function handleNav(id){document.querySelectorAll('.app-view').forEach(function(v){v.style.display='none'});var av=document.getElementById('view-'+id);if(av){av.style.display='flex';av.scrollTop=0}document.querySelectorAll('.sb-link').forEach(function(l){l.classList.toggle('active',l.dataset.section===id)})}

function toggleQN(){var p=document.getElementById('quicknav-panel'),f=document.getElementById('quicknav-fab');if(!p||!f)return;var o=p.classList.toggle('open');f.textContent=o?'✕':'⚡';f.classList.toggle('open',o)}
function closeQN(){var p=document.getElementById('quicknav-panel'),f=document.getElementById('quicknav-fab');if(!p||!f)return;p.classList.remove('open');f.classList.remove('open');f.textContent='⚡'}
function toggleFeedback(){var p=document.getElementById('feedback-panel');if(!p)return;var o=p.classList.toggle('open');document.getElementById('feedback-fab').textContent=o?'✕':'💬'}
function submitFeedback(){var t=document.getElementById('feedback-text');if(!t||!t.value.trim())return;var b=document.getElementById('feedback-body');b.innerHTML='<div style="text-align:center;padding:18px"><div style="font-size:2rem;margin-bottom:6px">✅</div><h3 style="font-weight:700;color:var(--white)">¡Gracias!</h3><p style="font-size:.78rem;color:var(--text2)">Comentario enviado.</p></div>';setTimeout(function(){toggleFeedback();setTimeout(function(){b.innerHTML='<div class="feedback-type"><button type="button" class="active" data-type="error">🐛 Error</button><button type="button" data-type="sugerencia">💡 Sugerencia</button></div><textarea class="feedback-textarea" id="feedback-text" placeholder="Describe tu sugerencia..."></textarea><button class="feedback-submit" id="feedback-submit-btn">Enviar</button>';b.querySelectorAll('.feedback-type button').forEach(function(btn){btn.addEventListener('click',function(){b.querySelectorAll('.feedback-type button').forEach(function(x){x.classList.remove('active')});btn.classList.add('active')})});document.getElementById('feedback-submit-btn').addEventListener('click',submitFeedback)},400)},2000)}
function setupEventListeners(){document.getElementById('topbar-toggle').addEventListener('click',function(){document.getElementById('sidebar').classList.toggle('open')});document.getElementById('sb-overlay').addEventListener('click',function(){document.getElementById('sidebar').classList.remove('open')});document.querySelectorAll('.sb-link').forEach(function(l){l.addEventListener('click',function(){handleNav(l.dataset.section);document.getElementById('sidebar').classList.remove('open')})});document.querySelectorAll('.hero-actions .btn').forEach(function(b){b.addEventListener('click',function(){handleNav(b.dataset.action)})});document.getElementById('quicknav-fab').addEventListener('click',toggleQN);document.querySelectorAll('.quicknav-item').forEach(function(i){i.addEventListener('click',function(){handleNav(i.dataset.section);closeQN()})});document.addEventListener('click',function(e){['topic-modal','lesson-modal','lab-modal','sim-modal','video-modal'].forEach(function(id){if(e.target.id===id){if(id==='video-modal')closeVideo();else closeModal(id)}});var qp=document.getElementById('quicknav-panel'),qf=document.getElementById('quicknav-fab');if(qp&&qp.classList.contains('open')&&!qp.contains(e.target)&&e.target!==qf)closeQN()});document.getElementById('feedback-fab').addEventListener('click',toggleFeedback);document.querySelectorAll('.feedback-type button').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('.feedback-type button').forEach(function(x){x.classList.remove('active')});b.classList.add('active')})});document.getElementById('feedback-submit-btn').addEventListener('click',submitFeedback);document.addEventListener('keydown',function(e){if(e.ctrlKey&&e.shiftKey&&(e.key==='Q'||e.key==='q')){e.preventDefault();document.getElementById('admin-overlay').classList.contains('open')?closeAdmin():openAdmin()}if(e.key==='Escape'){if(document.getElementById('admin-overlay').classList.contains('open')){closeAdmin();return}var o=document.querySelector('.modal-overlay.open');if(o){if(o.id==='video-modal')closeVideo();else closeModal(o.id)}if(document.getElementById('feedback-panel').classList.contains('open'))toggleFeedback();if(document.getElementById('quicknav-panel').classList.contains('open'))closeQN()}});document.getElementById('admin-apply').addEventListener('click',applyAdmin);document.getElementById('admin-download').addEventListener('click',downloadConfig);document.getElementById('admin-close').addEventListener('click',closeAdmin);}

